import{_ as a,a as s,b as i,c as t,d as p,e as o,f as r,g as n,h as l,i as d,j as c,k as m,l as h,m as u}from"./chunks/audio.Y4RIz_we.js";import{_ as g,o as f,c as b,a2 as x}from"./chunks/framework.BetZR81g.js";const S=JSON.parse('{"title":"Feature examples","description":"","frontmatter":{"lang":"en","sourcePath":"examples/features/README.md"},"headers":[],"relativePath":"examples/features.md","filePath":"examples/features.md"}'),w={name:"examples/features.md"};function v(k,e,y,j,E,_){return f(),b("div",null,[...e[0]||(e[0]=[x('<h1 id="feature-examples" tabindex="-1">Feature examples <a class="header-anchor" href="#feature-examples" aria-label="Permalink to &quot;Feature examples&quot;">​</a></h1><blockquote><p>Run from the sfml.js repository root after <code>npm ci</code>; run <code>npm run build</code> after source changes. All entries except Network open a graphical window and require a display with OpenGL support.</p></blockquote><p><a href="/examples">Overview</a> · <a href="/examples/official">Official examples</a> · <a href="/examples/projects">Games and applications</a></p><p>Run the commands below directly after building. The <code>demo:*</code> scripts in package.json rebuild as configured. Close the window to exit; entries with a frame limit also finish automatically. Screenshots show a particular rendered scene, not performance or device-test results.</p><p>For an application using only public APIs, start with the <a href="/guide/getting-started">Quick start</a>. Helpers are listed with their entry points, not as separate programs.</p><p><a id="system"></a></p><h2 id="system" tabindex="-1">System <a class="header-anchor" href="#system" aria-label="Permalink to &quot;System&quot;">​</a></h2><div class="example-gallery"><article class="example-entry" id="sleep-err"><a href="/media/examples/features/sleep-err.webp"><img src="'+a+'" width="360" alt="Asynchronous waiting and SFML log output"></a><div class="example-info"><p><strong><a href="https://github.com/XadillaX/node-sfml/blob/main/examples/sleep-err.cjs">sleep-err.cjs</a></strong></p><p>Asynchronous waiting and SFML log output</p><p><code>node examples/sleep-err.cjs</code></p><p>S waits two seconds; W writes a log; N triggers a native diagnostic; R captures logs in the panel, M mutes them, D restores stderr. Esc exits.</p><p>Optional frame limit: <code>--frames=120</code>.</p><p><code>npm run demo:sleep-err</code></p></div></article><article class="example-entry" id="vector-scalars"><a href="/media/examples/features/vector-scalars.webp"><img src="'+s+'" width="360" alt="Live scalar vector storage and native comparisons"></a><div class="example-info"><p><strong><a href="https://github.com/XadillaX/node-sfml/blob/main/examples/vector-scalars.cjs">vector-scalars.cjs</a></strong></p><p>Vector operations with different numeric scalar types</p><p><code>node examples/vector-scalars.cjs</code></p><p>Live TypedArray storage and native comparisons for scalar vector types. Esc exits.</p><p>No <code>--frames</code> option; close the window to stop.</p><p><strong>Repository diagnostic: uses internal native preview or verification APIs, not a public application template.</strong></p></div></article></div><p><a id="window"></a></p><h2 id="window" tabindex="-1">Window <a class="header-anchor" href="#window" aria-label="Permalink to &quot;Window&quot;">​</a></h2><div class="example-gallery"><article class="example-entry" id="window-demo"><a href="/media/examples/features/window.webp"><img src="'+i+'" width="360" alt="Window events, cursors and input diagnostics"></a><div class="example-info"><p><strong><a href="https://github.com/XadillaX/node-sfml/blob/main/examples/window.cjs">window.cjs</a></strong></p><p>Window events, cursors and input diagnostics</p><p><code>node examples/window.cjs</code></p><p>F1 cycles cursors, F2 toggles cursor visibility, F3 key repeat, F4 VSync, F5 window size, F6 size limits, F7 title, F8 hides/restores the window, F9 cycles event-handling modes, F10 moves the window. Arrows move the marker; typing edits text, Backspace deletes, Esc exits.</p><p>Optional frame limit: <code>--frames=120</code>.</p><p><strong>Repository diagnostic: uses internal native preview or verification APIs, not a public application template.</strong></p><p>Helpers: <a href="https://github.com/XadillaX/node-sfml/blob/main/examples/bitmap-label.cjs">bitmap-label.cjs</a></p><p><code>npm run demo:window</code></p></div></article><article class="example-entry" id="system-window"><a href="/media/examples/features/system-window.webp"><img src="'+t+'" width="360" alt="System and Window APIs"></a><div class="example-info"><p><strong><a href="https://github.com/XadillaX/node-sfml/blob/main/examples/system-window.cjs">system-window.cjs</a></strong></p><p>System and Window APIs</p><p><code>node examples/system-window.cjs</code></p><p>C copies sample text to the system clipboard, V reads it, A switches OpenGL contexts; Esc exits. Touch needs supported hardware; macOS trackpad gestures are not SFML touches.</p><p>Optional frame limit: <code>--frames=120</code>.</p><p><code>npm run demo:system-window</code></p></div></article></div><p><a id="graphics"></a></p><h2 id="graphics" tabindex="-1">Graphics <a class="header-anchor" href="#graphics" aria-label="Permalink to &quot;Graphics&quot;">​</a></h2><div class="example-gallery"><article class="example-entry" id="all-types"><a href="/media/examples/features/all-types.webp"><img src="'+p+'" width="360" alt="Combined scene with value types, transforms, shapes, vertices and text"></a><div class="example-info"><p><strong><a href="https://github.com/XadillaX/node-sfml/blob/main/examples/all-types.cjs">all-types.cjs</a></strong></p><p>Combined scene with value types, transforms, shapes, vertices and text</p><p><code>node examples/all-types.cjs</code></p><p>Optional frame limit: <code>--frames=120</code>.</p><p><strong>Repository diagnostic: uses internal native preview or verification APIs, not a public application template.</strong></p><p>Helpers: <a href="https://github.com/XadillaX/node-sfml/blob/main/examples/all-types-scene.cjs">all-types-scene.cjs</a>, <a href="https://github.com/XadillaX/node-sfml/blob/main/examples/bitmap-label.cjs">bitmap-label.cjs</a></p><p><code>npm run demo:types</code></p></div></article><article class="example-entry" id="sprites"><a href="/media/examples/features/sprites.webp"><img src="'+o+'" width="360" alt="Drawing large numbers of sprites"></a><div class="example-info"><p><strong><a href="https://github.com/XadillaX/node-sfml/blob/main/examples/sprites.cjs">sprites.cjs</a></strong></p><p>Drawing large numbers of sprites</p><p><code>node examples/sprites.cjs</code></p><p>256 animated sprites. Optional <code>--uncapped</code> removes the demo timer.</p><p>No <code>--frames</code> option; close the window to stop.</p><p><strong>Repository diagnostic: uses internal native preview or verification APIs, not a public application template.</strong></p><p><code>npm run demo</code></p></div></article><article class="example-entry" id="image"><a href="/media/examples/features/image.webp"><img src="'+r+'" width="360" alt="Pixel editing, copying, masking and codecs"></a><div class="example-info"><p><strong><a href="https://github.com/XadillaX/node-sfml/blob/main/examples/image.cjs">image.cjs</a></strong></p><p>Pixel editing, copying, masking and codecs</p><p><code>node examples/image.cjs</code></p><p>Optional <code>--file=/path/to/image.png</code> supplies an image.</p><p>Optional frame limit: <code>--frames=120</code>.</p><p><strong>Repository diagnostic: uses internal native preview or verification APIs, not a public application template.</strong></p><p>Helpers: <a href="https://github.com/XadillaX/node-sfml/blob/main/examples/bitmap-label.cjs">bitmap-label.cjs</a></p><p><code>npm run demo:image</code></p></div></article><article class="example-entry" id="texture"><a href="/media/examples/features/texture.webp"><img src="'+n+'" width="360" alt="Image loading, cropping, partial uploads and sampling"></a><div class="example-info"><p><strong><a href="https://github.com/XadillaX/node-sfml/blob/main/examples/texture.cjs">texture.cjs</a></strong></p><p>Image loading, cropping, partial uploads and sampling</p><p><code>node examples/texture.cjs</code></p><p>Optional frame limit: <code>--frames=120</code>.</p><p><strong>Repository diagnostic: uses internal native preview or verification APIs, not a public application template.</strong></p><p>Helpers: <a href="https://github.com/XadillaX/node-sfml/blob/main/examples/bitmap-label.cjs">bitmap-label.cjs</a></p><p><code>npm run demo:texture</code></p></div></article><article class="example-entry" id="sprite"><a href="/media/examples/features/sprite.webp"><img src="'+l+'" width="360" alt="Sprite animation, flipping, colors and bounds"></a><div class="example-info"><p><strong><a href="https://github.com/XadillaX/node-sfml/blob/main/examples/sprite.cjs">sprite.cjs</a></strong></p><p>Sprite animation, flipping, colors and bounds</p><p><code>node examples/sprite.cjs</code></p><p>Optional frame limit: <code>--frames=120</code>.</p><p><strong>Repository diagnostic: uses internal native preview or verification APIs, not a public application template.</strong></p><p>Helpers: <a href="https://github.com/XadillaX/node-sfml/blob/main/examples/bitmap-label.cjs">bitmap-label.cjs</a></p><p><code>npm run demo:sprite</code></p></div></article><article class="example-entry" id="render-texture"><a href="/media/render-texture.png"><img src="'+d+'" width="360" alt="Off-screen composition, texture views and draw snapshots"></a><div class="example-info"><p><strong><a href="https://github.com/XadillaX/node-sfml/blob/main/examples/render-texture.cjs">render-texture.cjs</a></strong></p><p>Off-screen composition, texture views and draw snapshots</p><p><code>node examples/render-texture.cjs</code></p><p>Optional frame limit: <code>--frames=120</code>.</p><p><strong>Repository diagnostic: uses internal native preview or verification APIs, not a public application template.</strong></p><p>Helpers: <a href="https://github.com/XadillaX/node-sfml/blob/main/examples/bitmap-label.cjs">bitmap-label.cjs</a></p><p><code>npm run demo:render-texture</code></p></div></article><article class="example-entry" id="drawable"><a href="/media/examples/features/drawable.webp"><img src="'+c+'" width="360" alt="Custom composition, parent-child transforms, blending and stencil"></a><div class="example-info"><p><strong><a href="https://github.com/XadillaX/node-sfml/blob/main/examples/drawable.cjs">drawable.cjs</a></strong></p><p>Custom composition, parent-child transforms, blending and stencil</p><p><code>node examples/drawable.cjs</code></p><p>Optional frame limit: <code>--frames=120</code>.</p><p><strong>Repository diagnostic: uses internal native preview or verification APIs, not a public application template.</strong></p><p>Helpers: <a href="https://github.com/XadillaX/node-sfml/blob/main/examples/bitmap-label.cjs">bitmap-label.cjs</a></p><p><code>npm run demo:drawable</code></p></div></article><article class="example-entry" id="vertex-array"><a href="/media/examples/features/vertex-array.webp"><img src="'+m+'" width="360" alt="Dynamic tiles and contiguous vertices"></a><div class="example-info"><p><strong><a href="https://github.com/XadillaX/node-sfml/blob/main/examples/vertex-array.cjs">vertex-array.cjs</a></strong></p><p>Dynamic tiles and contiguous vertices</p><p><code>node examples/vertex-array.cjs</code></p><p>Optional frame limit: <code>--frames=120</code>.</p><p><strong>Repository diagnostic: uses internal native preview or verification APIs, not a public application template.</strong></p><p><code>npm run demo:vertices</code></p></div></article><article class="example-entry" id="text"><a href="/media/examples/features/text.webp"><img src="'+h+'" width="360" alt="Text layout and vertex animation"></a><div class="example-info"><p><strong><a href="https://github.com/XadillaX/node-sfml/blob/main/examples/text.cjs">text.cjs</a></strong></p><p>Text layout and vertex animation</p><p><code>node examples/text.cjs</code></p><p>Optional <code>--font=/path/to/font.ttf</code> and <code>--text=Hello</code> select font and text. The font must contain the requested glyphs. Esc exits.</p><p>Optional frame limit: <code>--frames=120</code>.</p><p><code>npm run demo:text</code></p></div></article></div><p><a id="audio"></a></p><h2 id="audio" tabindex="-1">Audio <a class="header-anchor" href="#audio" aria-label="Permalink to &quot;Audio&quot;">​</a></h2><div class="example-gallery"><article class="example-entry" id="audio-demo"><a href="/media/examples/features/audio.webp"><img src="'+u+`" width="360" alt="Sound, Music, Worker data production, effects and recording playback"></a><div class="example-info"><p><strong><a href="https://github.com/XadillaX/node-sfml/blob/main/examples/audio.cjs">audio.cjs</a></strong></p><p>Sound, Music, Worker data production, effects and recording playback</p><p><code>node examples/audio.cjs</code></p><p>1–4 select modes, Space plays/pauses, S stops, E toggles effects, R/T start/stop recording, arrows adjust pan/volume, Esc exits. Recording needs a microphone and permission; ordinary startup waits for input.</p><p>Optional frame limit: <code>--frames=120</code>.</p><p>Helpers: <a href="https://github.com/XadillaX/node-sfml/blob/main/examples/audio-worker.cjs">audio-worker.cjs</a></p><p><code>npm run demo:audio</code></p></div></article></div><p><a id="network"></a></p><h2 id="network" tabindex="-1">Network <a class="header-anchor" href="#network" aria-label="Permalink to &quot;Network&quot;">​</a></h2><div class="example-gallery"><article class="example-entry" id="network-demo"><div class="example-info"><p><strong><a href="https://github.com/XadillaX/node-sfml/blob/main/examples/network.cjs">network.cjs</a></strong></p><p>Local TCP, Packet, UDP and Selector</p><p><code>node examples/network.cjs</code></p><p>Console-only local TCP, Packet, UDP and SocketSelector exchange on dynamically allocated loopback ports; runs in one terminal and closes its sockets automatically.</p><p><code>npm run demo:network</code></p></div></article></div><p><a id="screenshots"></a></p><h2 id="screenshots" tabindex="-1">Screenshots <a class="header-anchor" href="#screenshots" aria-label="Permalink to &quot;Screenshots&quot;">​</a></h2><p>Graphics examples supporting <code>SFML_DEMO_SNAPSHOT</code> can save their rendered output. For example, on macOS/Linux:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SFML_DEMO_SNAPSHOT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/tmp/sfml-render-texture.png</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/render-texture.cjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --frames=2</span></span></code></pre></div><p>PowerShell:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">env:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SFML_DEMO_SNAPSHOT </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">env:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">TEMP</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/sfml-render-texture.png&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">node examples</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">render</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">texture.cjs </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">frames</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Remove-Item</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Env:SFML_DEMO_SNAPSHOT</span></span></code></pre></div><p>Built-in snapshots use <code>SFML_DEMO_SNAPSHOT</code>. all-types, sprites, drawable, vertex-array, system-window and sleep-err write PPM regardless of the filename extension; use <code>.ppm</code>. image, texture, sprite, render-texture, window and audio support PNG. text and vector-scalars do not implement this environment variable; their previews were captured with temporary instrumentation.</p><p>Use a finite frame count for sleep-err (saved at the last frame) and vertex-array (saved after the loop). system-window, window and audio need at least two frames; other built-in previews may capture the first frame. sprites captures its first frame and keeps running until closed. Capture provenance is recorded in <a href="/media/examples/features/sources.json">sources.json</a>.</p>`,28)])])}const P=g(w,[["render",v]]);export{S as __pageData,P as default};
